"""生成测试用的广东省考职位表样本（6 sheet，合成数据，无个人信息）。

为什么不能直接用真实职位表：真实表含招录单位联系方式与岗位细节，且体量大、变动频繁。
这里按真实表的结构（6 sheet、表头在第 2 行、列名与广东一致）构造**结构等价**的合成样本，
用于验证解析器与各引擎模块的行为，不用于产出任何真实选岗结论。

样本刻意覆盖改造方案的三个验收岗（REQ-001）：
  - 广州市南沙区应急管理局（intro 含「应急」「三防」）→ heavy
  - 广州市公安局从化区分局江埔派出所（intro 含「执法」「执勤」）→ heavy
  - 广州市白云区嘉禾街道办事处（intro 含「三防」「应急」）→ heavy
以及两个反例（intro 干净、但结构化字段看着"正常"的综合岗），用于验证不会误判。

用法：python tests/fixtures/build_gd_sample.py
"""

from __future__ import annotations

import argparse
import sys
from pathlib import Path

try:
    from openpyxl import Workbook
except ImportError:  # pragma: no cover - 环境缺 openpyxl 时明确失败
    print("需要 openpyxl 生成样本：pip install openpyxl", file=sys.stderr)
    raise SystemExit(3)

OUT = Path(__file__).with_name("gd-2026-jobs.xlsx")

# 表头（与广东省考职位表一致；表头实际写在第 2 行，第 1 行是标题行）
HEADERS = [
    "职位代码",
    "招考单位",
    "招考职位",
    "职位简介",
    "录用人数",
    "学历",
    "专业名称及代码",
    "是否要求2年以上基层工作经历",
    "其他要求",
    "考区",
    "报名人数",
]

# 每个 sheet 的岗位（合成）；「乡镇机关」sheet 的岗位应被判 5 年服务期
SHEETS: dict[str, list[list[str]]] = {
    "县以上机关": [
        # 南沙区发改局：强度 none，薪酬高档（25-27 万），2 年基层要求
        [
            "44010100000001", "广州市南沙区发展和改革局", "一级科员",
            "从事经济社会发展规划编制工作", "1", "本科",
            "经济学(B020101),法学(B030101)", "是", "无", "广州市南沙区", "48",
        ],
        # 荔湾区政数局：强度 none，薪酬低档（18-21 万）
        [
            "44010100000002", "广州市荔湾区政务服务和数据管理局", "一级科员",
            "从事政务服务信息化建设", "1", "本科",
            "计算机类(B0809),法学(B030101)", "否", "无", "广州市荔湾区", "132",
        ],
        # 从化区民政局：强度 none，薪酬最低档（15-18 万）
        [
            "44010100000003", "广州市从化区民政局", "一级科员",
            "从事社会救助审核工作", "1", "本科",
            "法学(B030101),社会学类(B0303)", "否", "无", "广州市从化区", "86",
        ],
        # ★ REQ-001 验收岗 1：南沙区应急管理局（intro 含应急/三防）→ 必须 heavy
        [
            "44010100000004", "广州市南沙区应急管理局", "一级科员",
            "从事应急管理、三防指挥及综合协调工作", "1", "本科",
            "法学(B030101),安全科学与工程类(B0830)", "否", "无", "广州市南沙区", "57",
        ],
        # 反例：开发区投促局，intro 干净（不含任何强度词）→ none
        [
            "44010100000005", "广州市黄埔区投资促进局", "一级科员",
            "从事招商引资项目跟踪与合同管理工作", "1", "本科",
            "法学(B030101),经济学类(B0201)", "否", "无", "广州市黄埔区", "210",
        ],
    ],
    "公安机关": [
        # ★ REQ-001 验收岗 2：江埔派出所（intro 含执法/执勤）→ 必须 heavy
        [
            "44010200000001", "广州市公安局从化区分局江埔派出所", "二级警长以下",
            "从事一线执法执勤工作", "3", "本科",
            "法学(B030101),公安学类(B0306)", "否", "需体能测评", "广州市从化区", "95",
        ],
    ],
    "法院": [
        [
            "44010300000001", "广州市荔湾区人民法院", "五级法官助理",
            "从事审判辅助工作", "2", "本科",
            "法学(B030101)", "否", "须通过法律职业资格考试", "广州市荔湾区", "64",
        ],
    ],
    "检察院": [
        [
            "44010400000001", "广州市从化区人民检察院", "五级检察官助理",
            "从事检察辅助工作", "1", "本科",
            "法学(B030101)", "否", "须通过法律职业资格考试", "广州市从化区", "31",
        ],
    ],
    "监狱": [
        # 值班岗：intro 含「夜间值班」→ heavy
        [
            "44010500000001", "广东省广州监狱", "二级警长以下",
            "从事监所管理及夜间值班工作", "2", "本科",
            "法学(B030101),监所管理(B0306)", "否", "需体能测评，适合男性", "广州市白云区", "77",
        ],
    ],
    "乡镇机关": [
        # ★ REQ-001 验收岗 3：嘉禾街道（intro 含三防/应急）→ heavy，且 5 年服务期
        [
            "44010600000001", "广州市白云区嘉禾街道办事处", "一级科员",
            "从事三防应急及综合管理工作", "1", "本科",
            "法学(B030101),公共管理类(B1204)", "否", "在乡镇机关最低服务5年", "广州市白云区", "41",
        ],
        # 乡镇岗但强度 none：用于验证「5 年服务期」判定不依赖强度
        [
            "44010600000002", "广州市从化区江埔街道办事处", "一级科员",
            "从事文电会务及档案管理工作", "1", "本科",
            "法学(B030101),中国语言文学类(B0501)", "否", "在乡镇机关最低服务5年", "广州市从化区", "38",
        ],
    ],
}


def build(out: Path = OUT) -> Path:
    wb = Workbook()
    wb.remove(wb.active)
    for sheet_name, rows in SHEETS.items():
        ws = wb.create_sheet(sheet_name)
        # 第 1 行为标题行（真实表也是这种两行表头结构）
        ws.append([f"广东省2026年考试录用公务员职位表（{sheet_name}）"])
        ws.append(HEADERS)
        for row in rows:
            ws.append(row)
    wb.save(out)
    return out


if __name__ == "__main__":
    parser = argparse.ArgumentParser(description="生成广东省考职位表测试样本（合成数据）")
    parser.add_argument("--out", default=str(OUT), help="输出路径（缺省为同目录 gd-2026-jobs.xlsx）")
    args = parser.parse_args()
    print(build(Path(args.out)))
